{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "생활권별로 자전거주차장·보관소·수리센터·대여소를 묶어 운영하는 방안을 시가 추진하도록 한 규정 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제12조에 따르면, 시장은 생활권이나 여가활동권 단위(권역)로 자전거이용이 활성화되도록 자전거주차장·보관소·수리센터·대여소 등을 권역별로 통합하여 운영하기 위한 시책을 개발하여 추진하여야 한다. 따라서 생활권별로 해당 시설을 묶어 운영하는 방안을 시가 추진하도록 한 규정이 있다.",
          "b_ids": "자전거:제12조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
